  return t.length > n ? `${t.slice(0, n - 1)}…` : t;
};

// ---------- Поиск куска текста ----------

// Нормализация для поиска: пробелы подряд → один, кавычки → ", тире → -, ё → е, маркеры списка → -.
// out — строка, pos — позиция каждого её знака в исходнике
function normMap(text) {
  let out = '';
  const pos = [];
  let space = false;
  for (let i = 0; i < text.length; i++) {
    let c = text[i];
    if (/\s/.test(c)) {
      if (!space && out.length) {
        out += ' ';
        pos.push(i);
      }
      space = true;
      continue;
    }
    space = false;
    if ('«»“”„"'.includes(c)) c = '"';
    else if ('—–‒−'.includes(c)) c = '-';
    else if (c === '•' || c === '·') c = '-';
    else if (c === 'ё') c = 'е';
    else if (c === 'Ё') c = 'Е';
    out += c;
    pos.push(i);
  }
  if (out.endsWith(' ')) {
    out = out.slice(0, -1);
    pos.pop();
  }
  return { out, pos };
}

// Где в тексте кусок old: { start, end } — позиции в исходнике, или { error: none | many }
function locateSnippet(text, old) {
  const needle = String(old ?? '');
  if (!needle.trim()) return { error: 'none' };
  const first = text.indexOf(needle);
  if (first >= 0) return text.indexOf(needle, first + 1) >= 0 ? { error: 'many' } : { start: first, end: first + needle.length };
  // Нейросеть поменяла пробелы, кавычки или тире — ищем без них и переводим обратно в позиции исходника
  const t = normMap(text);
  const n = normMap(needle.trim()).out;
  const at = n ? t.out.indexOf(n) : -1;
  if (at < 0) return { error: 'none' };
  if (t.out.indexOf(n, at + 1) >= 0) return { error: 'many' };
  return { start: t.pos[at], end: t.pos[at + n.length - 1] + 1 };
}

// В какой части черновика кусок: resume, extra или null — задевает обе или заголовок «Дополнительно»
function partOf(d, at) {
  if (at.end <= d.resume.length) return 'resume';
  if (d.extra && at.start >= d.resume.length + EXTRA_HEAD.length) return 'extra';
  return null;
}

// ---------- Правка ----------

// Слова для сравнения: без регистра и знаков препинания по краям («React.» = «react», «Next.js» и «C++» — целиком)
const patchWords = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .match(/[\p{L}\p{N}](?:[\p{L}\p{N}.+#-]*[\p{L}\p{N}+#])?/gu) ?? [];

// Добавление — все слова old по порядку остались в new. Иначе замена: что-то из старого текста пропадёт
function isAddition(old, next) {
  const a = patchWords(old);
  let i = 0;
  for (const w of patchWords(next)) if (i < a.length && w === a[i]) i++;
  return i === a.length;
}

const PATCH_MAX = 1500;
const PATCH_ERRORS = {
  none: 'не нашёл это место в тексте',
  many: 'такой кусок встречается в тексте несколько раз',
  same: 'правка ничего не меняет',
  long: 'слишком длинная правка',
  edge: 'правка задевает и резюме, и «Дополнительно»',
  cross: 'правка задевает два раздела резюме',
  scope: 'правка не про опыт работы',
  mark: 'в правке служебные знаки ⟦ ⟧',
  limit: 'резюме вышло бы длиннее предела',
  overlap: 'то же место уже правит другая правка',
};

// Правка нейросети → { where, old, new, why, kind: add | replace, section, start, end } (old — точный кусок исходника)
// или { error }. section — раздел (n8n/shared/cv.js: title, about, p:e1, d:e1) или text, extra. Пустой old и where
// «Дополнительно» — новая строка в конец profile.extra (append): у человека, который «Дополнительно» ещё не писал, свои
// проекты больше некуда вписать. scope experience — только правки опыта работы (Upgrade из «💼 Опыт работы»)
function checkPatch(d, p, scope = '') {
  const old = String(p?.old ?? '');
  const next = String(p?.new ?? '').trim();
  const where = oneLine(p?.where, 60) || 'Резюме';
  if (CV_BAD.test(next)) return { error: 'mark' };
  if (!old.trim()) {
    if (!/дополнительно/i.test(where) || !next) return { error: 'none' };
    if (next.length > PATCH_MAX) return { error: 'long' };
    if (scope === 'experience') return { error: 'scope' };
    return { where, old: '', new: next, why: oneLine(p?.why, 200), kind: 'add', section: 'extra', append: 'extra', start: -1, end: -1 };
  }
  if (normMap(old).out === normMap(next).out) return { error: 'same' };
  if (next.length > PATCH_MAX || old.length > PATCH_MAX * 2) return { error: 'long' };
  const text = resumeJoin(d);
  const at = locateSnippet(text, old);
  if (at.error) return { error: at.error };
  const part = partOf(d, at);
  if (!part) return { error: 'edge' };
  let section = part === 'extra' ? 'extra' : 'text';
  if (part === 'resume' && d.cv) {
    const c = cvPartAt(d.cv, at);
    if (!c) return { error: 'cross' };
    section = c.key;
  }
  if (scope === 'experience' && !cvShared(section)) return { error: 'scope' };
  // old — точный кусок исходника: нейросеть могла поменять в нём пробелы или кавычки, применять будем к исходнику
  const exact = text.slice(at.start, at.end);
  return {
    where,
    old: exact,
    new: next,
    why: oneLine(p?.why, 200),
    kind: isAddition(exact, next) ? 'add' : 'replace',
    section,
    start: at.start,
    end: at.end,
  };
}

// Правки нейросети → { patches, dropped: [{ where, error }] }: проверенные, без пересечений, не больше max
function checkPatches(d, list, max = 8, scope = '') {
  const patches = [];
  const dropped = [];
  for (const p of (Array.isArray(list) ? list : []).slice(0, max * 2)) {
    const c = checkPatch(d, p, scope);
    if (c.error) dropped.push({ where: oneLine(p?.where, 60) || 'Резюме', error: c.error });
    else if (!c.append && patches.some((x) => c.start < x.end && x.start < c.end)) dropped.push({ where: c.where, error: 'overlap' });
    else if (patches.length < max) patches.push(c);
  }
  return { patches, dropped };
}

// Применить правку к черновику: old ищется заново — прошлая правка могла его поменять. → { draft } или { error }
function applyPatch(d, p) {
  if (p.append === 'extra') {
    const extra = d.extra ? `${d.extra}\n${p.new}` : p.new;
    return extra.length > SETTINGS['profile.extra'].text ? { error: 'limit' } : { draft: { ...d, extra } };
  }
  const at = locateSnippet(resumeJoin(d), p.old);
  if (at.error) return { error: at.error };
  const part = partOf(d, at);
  if (!part) return { error: 'edge' };
  if (part === 'resume' && d.cv) {
    // Разметка: правится поле раздела (или текст вокруг меток), текст резюме — рендер
    const r = cvApply(d.cv, at, p.new);
    if (r.error) return r;
    const resume = cvRender(r.cv);
    return resume.length > SETTINGS['profile.resume'].text ? { error: 'limit' } : { draft: { ...d, resume, cv: r.cv } };
  }
  const offset = part === 'resume' ? 0 : d.resume.length + EXTRA_HEAD.length;
  const src = d[part];
  const value = src.slice(0, at.start - offset) + p.new + src.slice(at.end - offset);
  const limit = SETTINGS[part === 'resume' ? 'profile.resume' : 'profile.extra'].text;
  if (value.length > limit) return { error: 'limit' };
  return { draft: { ...d, [part]: value } };
}

// ---------- Дифф для Telegram ----------

// Пословный дифф (HTML): <s>убрал</s> <b>добавил</b>; длинные куски без изменений сжаты до «…» с context словами вокруг
function wordDiff(old, next, context = 8, max = 1800) {
  const a = String(old ?? '').split(/\s+/).filter(Boolean);
  const b = String(next ?? '').split(/\s+/).filter(Boolean);
  const key = (w) => patchWords(w).join(' ') || w;
  const ka = a.map(key);
  const kb = b.map(key);
  // LCS: dp[i][j] — длина общей подпоследовательности хвостов a[i:] и b[j:]
  const dp = Array.from({ length: a.length + 1 }, () => new Uint16Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) dp[i][j] = ka[i] === kb[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  }
  const ops = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && ka[i] === kb[j]) {
      ops.push(['=', b[j++]]);
      i++;
    } else if (i < a.length && (j >= b.length || dp[i + 1][j] >= dp[i][j + 1])) ops.push(['-', a[i++]]);
    else ops.push(['+', b[j++]]);
  }
  // Склеить подряд идущие слова одного вида
  const runs = [];
  for (const [t, w] of ops) {
    if (runs.at(-1)?.[0] === t) runs.at(-1)[1].push(w);
    else runs.push([t, [w]]);
  }
  const html = runs
    .map(([t, words], n) => {
      if (t === '-') return `<s>${esc(words.join(' '))}</s>`;
      if (t === '+') return `<b>${esc(words.join(' '))}</b>`;
      const first = n === 0;
      const last = n === runs.length - 1;
      const keep = (first ? 0 : context) + (last ? 0 : context);
      if (words.length <= keep + 3) return esc(words.join(' '));
      const head = first ? [] : words.slice(0, context);
      const tail = last ? [] : words.slice(-context);
      return [...head, '…', ...tail].map(esc).join(' ');
    })
    .join(' ');
  return html.length > max ? `${html.slice(0, max).replace(/<[^>]*$/, '')}…` : html;
}

// ---------- Навыки вакансий ----------

// Вакансии, которые человек выбрал или выбрал бы: ✅ 🤔 📨 или решения нет, а нейросеть сказала apply
const isTargetRow = (r) => ['apply', 'maybe', 'earlier'].includes(r.my_decision) || (!r.my_decision && r.decision === 'apply');
// Ключ навыка для подсчёта: «React.js» = «ReactJS» = «react», «HTML5» = «HTML», «postgres» = «PostgreSQL»
const SKILL_SYNONYMS = { postgres: 'postgresql', kuber: 'kubernetes', k8s: 'kubernetes' };
function skillKey(skill) {
  const s = String(skill ?? '').toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ').trim();
  const base = (s.length > 3 ? s.replace(/\.?js$/, '') : s).replace(/^([a-z][a-z.+#-]{2,})\d+$/, '$1');
  return SKILL_SYNONYMS[base] ?? base;
}
// Есть ли навык в тексте резюме (в нижнем регистре): как mentionsSkill, но с номером версии после — «HTML» есть в
// «HTML5/CSS3», «CSS» — тоже
const hasSkill = (text, name) =>
  skillVariants(name).some((v) =>
    new RegExp(`(^|[^a-zа-яё0-9])${v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\d*([^a-zа-яё0-9]|$)`).test(text),
  );

// Навыки вакансий против резюме. rows — строки vacancies, text — резюме одним текстом.
// → { basis: target | passed | null, vacancies, coverage (0–1 или null), top: [{ name, freq, has }], missing }
//   basis target — вакансии, которые человек выбрал (их меньше 10 — passed: все, что прошли фильтр).
//   coverage — доля частот навыков из top, которые есть в резюме
function skillStats(rows, text, top = 30) {
  const withSkills = (rows ?? []).filter((r) => r?.key_skills);
  let basis = 'target';
  let list = withSkills.filter(isTargetRow);
  if (list.length < 10) {
    basis = 'passed';
    list = withSkills.filter((r) => !['rejected', 'seen'].includes(r.status));
  }
  if (!list.length) return { basis: null, vacancies: 0, coverage: null, top: [], missing: [] };
  const counts = new Map();
  for (const r of list) {
    const seen = new Set();
    for (const raw of String(r.key_skills).split(',').map((x) => x.trim()).filter(Boolean)) {
      const key = skillKey(raw);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      const c = counts.get(key) ?? { freq: 0, names: new Map() };
      c.freq++;
      c.names.set(raw, (c.names.get(raw) ?? 0) + 1);
      counts.set(key, c);
    }
  }
  const low = String(text ?? '').toLowerCase();
  const skills = [...counts.values()]
    .map((c) => {
      const names = [...c.names.entries()].sort((x, y) => y[1] - x[1]).map(([n]) => n);
      return { name: names[0], freq: c.freq, has: names.some((n) => hasSkill(low, n)) };
    })
    .sort((x, y) => y.freq - x.freq || x.name.localeCompare(y.name))
    .slice(0, top);
  const total = skills.reduce((n, x) => n + x.freq, 0);
  const got = skills.reduce((n, x) => n + (x.has ? x.freq : 0), 0);
  return { basis, vacancies: list.length, coverage: total ? got / total : null, top: skills, missing: skills.filter((x) => !x.has) };
}

const percent = (x) => `${Math.round((x ?? 0) * 100)}%`;

// Частые слова в названиях подходящих вакансий (анализ: как называть должность) → [{ word, freq }]
const TITLE_STOP = new Set(['в', 'на', 'и', 'с', 'по', 'для', 'к', 'из', 'от', 'до', 'или', 'the', 'of', 'and', 'to', 'in', 'for', 'a']);
function titleWords(rows, top = 12) {
  const list = (rows ?? []).filter(isTargetRow);
  const counts = new Map();
  for (const r of list.length >= 10 ? list : (rows ?? []).filter((x) => !['rejected', 'seen'].includes(x?.status))) {
    const words = new Set(String(r?.title ?? '').toLowerCase().replace(/ё/g, 'е').match(/[\p{L}\p{N}][\p{L}\p{N}.+#-]*/gu) ?? []);
    for (const w of words) if (!TITLE_STOP.has(w) && w.length > 1) counts.set(w, (counts.get(w) ?? 0) + 1);
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, top).map(([word, freq]) => ({ word, freq }));
}

// Разделы резюме (W13, 15.10.2026, docs/recommendations.md → «Разделы резюме»): разметка поверх текста.
// Подключение: «// @include n8n/shared/cv.js» сразу после n8n/shared/resume.js (locateSnippet, normMap).
//
// Текст резюме (profile.resume) остаётся как есть — разделы это именованные куски текста. Настройка cv хранит текст
// с метками вместо кусков (template) и сами куски:
//   ⟦title⟧, ⟦about⟧ — должность и «О себе» резюме (cv.resumes[i]: несколько резюме заложены, пока одно);
//   ⟦p:e1⟧, ⟦d:e1⟧ — должность и описание места работы (cv.places — общие для всех резюме: на hh опыт работы хранится
//   в профиле, E0). Компания и даты места остаются в тексте вокруг меток: личные факты, их не правим.
// cvRender(cv) === profile.resume — иначе разметка устарела (резюме переписал W11 или импорт): W13 работает с текстом.
// keySkills резюме — ключевые навыки для hh (≤ 30, выбирает человек); в текст не попадают: навык из пет-проекта в общем
// списке W5 счёл бы коммерческим опытом.

const CV_MARK = /⟦(title|about|[pd]:e\d{1,3})⟧/g;
// Ключевых навыков на hh — не больше 30 (_conditions.keySkills.maxcount, E0)
const KEY_SKILLS_MAX = 30;
const CV_BAD = /[⟦⟧]/;

// Значение поля по ключу метки
function cvField(cv, key, i = 0) {
  if (key === 'title' || key === 'about') return cv.resumes[i][key];
  const place = cv.places.find((p) => p.id === key.slice(2));
  return (key[0] === 'p' ? place?.position : place?.description) ?? '';
}

// Текст резюме из разметки
const cvRender = (cv, i = 0) => cv.resumes[i].template.replace(CV_MARK, (m, key) => cvField(cv, key, i));

// Разметка жива: рендер совпадает с profile.resume (так же без пробелов по краям, как resumeDraft)
function cvFresh(s) {
  try {
    return Boolean(s.cv?.resumes?.length) && cvRender(s.cv) === String(s['profile.resume'] ?? '').trim();
  } catch {
    return false;
  }
}

// Куски отрендеренного текста по порядку: { key: title | about | p:e1 | d:e1 | text, start, end, t } — t: где кусок
// text начинается в template (длина у него та же)
function cvLayout(cv, i = 0) {
  const tpl = cv.resumes[i].template;
  const parts = [];
  let pos = 0;
  let last = 0;
  for (const m of tpl.matchAll(CV_MARK)) {
    if (m.index > last) {
      parts.push({ key: 'text', start: pos, end: pos + m.index - last, t: last });
      pos += m.index - last;
    }
    const len = cvField(cv, m[1], i).length;
    parts.push({ key: m[1], start: pos, end: pos + len });
    pos += len;
    last = m.index + m[0].length;
  }
  if (tpl.length > last) parts.push({ key: 'text', start: pos, end: pos + tpl.length - last, t: last });
  return parts;
}

// Раздел, в котором целиком лежит кусок at = { start, end } текста, или null — кусок задевает два раздела
const cvPartAt = (cv, at, i = 0) => cvLayout(cv, i).find((p) => p.end > p.start && at.start >= p.start && at.end <= p.end) ?? null;

// Поменять кусок at текста на next → { cv, section } или { error: cross | mark }: правится поле раздела или текст
// вокруг меток (template). Исходный cv не меняется
function cvApply(cv, at, next, i = 0) {
  if (CV_BAD.test(next)) return { error: 'mark' };
  const part = cvPartAt(cv, at, i);
  if (!part) return { error: 'cross' };
  const off = at.start - part.start;
  const cut = (s) => s.slice(0, off) + next + s.slice(off + at.end - at.start);
  const copy = JSON.parse(JSON.stringify(cv));
  const r = copy.resumes[i];
  if (part.key === 'text') {
    r.template = r.template.slice(0, part.t) + cut(r.template.slice(part.t, part.t + part.end - part.start)) + r.template.slice(part.t + part.end - part.start);
  } else if (part.key === 'title' || part.key === 'about') r[part.key] = cut(r[part.key]);
  else {
    const place = copy.places.find((p) => p.id === part.key.slice(2));
    const field = part.key[0] === 'p' ? 'position' : 'description';
    place[field] = cut(place[field]);
  }
  return { cv: copy, section: part.key };
}

// Раздел опыта работы (общий для всех резюме)
const cvShared = (section) => /^[pd]:/.test(String(section ?? ''));

// Подпись раздела для Telegram (без HTML): «Должность», «💼 Руб Икс — описание»… или '' — текст вне разделов
function cvSectionName(cv, section) {
  if (section === 'title') return 'Должность';
  if (section === 'about') return '«О себе»';
  if (section === 'extra') return '«Дополнительно»';
  if (!cvShared(section)) return '';
  const place = cv?.places.find((p) => p.id === section.slice(2));
  return `💼 ${place?.company || 'Место работы'} — ${section[0] === 'p' ? 'должность' : 'описание'}`;
}

// ---------- Разметка из якорей нейросети (режим split) ----------

// Первое вхождение needle в [lo, hi) — дословно или без разницы в пробелах, кавычках и тире (как locateSnippet).
// Первое, а не единственное: желаемая должность в PDF hh часто совпадает с должностью на последнем месте работы, а
// места идут по порядку — каждое ищется от конца прошлого. Потерю текста ловит проверка рендером
function cvFind(text, needle, lo = 0, hi = text.length) {
  const area = text.slice(lo, hi);
  const at = locateSnippet(area, needle);
  if (at.error !== 'many') return at.error ? at : { start: lo + at.start, end: lo + at.end };
  const i = area.indexOf(String(needle));
  if (i >= 0) return { start: lo + i, end: lo + i + String(needle).length };
  const m = normMap(area);
  const n = normMap(String(needle).trim()).out;
  const k = m.out.indexOf(n);
  return { start: lo + m.pos[k], end: lo + m.pos[k + n.length - 1] + 1 };
}
// Последнее дословное вхождение в [lo, hi) (ближайшее к hi), иначе — как cvFind
function cvLast(text, needle, lo, hi) {
  const i = text.lastIndexOf(String(needle), hi - String(needle).length);
  return i >= lo ? { start: i, end: i + String(needle).length } : cvFind(text, needle, lo, hi);
}
// Якорь целиком, иначе — его голова (head) или хвост (tail), от 3 слов. Длинный якорь нейросеть иногда путает с другого
// края: 15.10.2026 Flash-Lite вернул конец «О себе» как «HTML5/CSS3, Storybook, …», а в тексте «SSR/SSG/CSR, Storybook, …»
function cvFindPart(text, needle, lo, hi, side) {
  const words = String(needle ?? '').trim().split(/\s+/);
  for (let k = words.length; k >= Math.min(3, words.length); k--) {
    const r = cvFind(text, (side === 'head' ? words.slice(0, k) : words.slice(-k)).join(' '), lo, hi);
    if (!r.error) return r;
  }
  return { error: 'none' };
}
// Кусок from…to: начало from в [lo, hi), конец — первое to после него. → { start, end } или { error }
function cvSpan(text, from, to, lo = 0, hi = text.length) {
  const a = cvFindPart(text, from, lo, hi, 'head');
  if (a.error) return a;
  const b = cvFindPart(text, to, a.start, hi, 'tail');
  return b.error ? b : { start: a.start, end: b.end };
}

// a = { title, about: { from, to }, places: [{ company, period, position, from, to }] } — всё дословно из text.
// Описание места — от from до to; компания, даты и должность ищутся в заголовке места: между концом прошлого места и
// началом описания (должность может встретиться и в «О себе»). Не нашлось — раздел остаётся текстом, причина — в
// problems. → { cv, problems } или { error: mark | lossy }
function cvFromAnchors(text, a) {
  if (CV_BAD.test(text)) return { error: 'mark' };
  const problems = [];
  const ranges = [];
  const free = (r) => !ranges.some((x) => r.start < x.end && x.start < r.end);
  const take = (key, r, label) => {
    if (r.error) problems.push(`${label}: не нашёл в тексте`);
    else if (!free(r) || r.end <= r.start) problems.push(`${label}: пересекается с другим разделом`);
    else {
      ranges.push({ key, ...r });
      return true;
    }
    return false;
  };
  if (a?.title) take('title', cvFind(text, a.title), 'должность');
  if (a?.about?.from && a?.about?.to) take('about', cvSpan(text, a.about.from, a.about.to), '«О себе»');
  const places = [];
  let lo = 0;
  for (const p of Array.isArray(a?.places) ? a.places.slice(0, 30) : []) {
    const company = String(p?.company ?? '').trim();
    const label = `место «${company || '?'}»`;
    const id = `e${places.length + 1}`;
    const d = p?.from && p?.to ? cvSpan(text, p.from, p.to, lo) : { error: 'none' };
    if (d.error) {
      problems.push(`${label}: не нашёл описание`);
      continue;
    }
    // Заголовок места — от компании (последнее её упоминание перед описанием) до описания; компании дословно нет —
    // 300 знаков перед описанием
    const c = company ? text.lastIndexOf(company, d.start) : -1;
    const head = c >= lo ? Math.max(lo, c - 200) : Math.max(lo, d.start - 300);
    // Должность — после компании («### Компания — Должность», в PDF hh — строкой ниже), иначе ближайшая перед ней
    let pos = { error: 'none' };
    if (p?.position && c >= lo) {
      pos = cvFind(text, p.position, c, d.start);
      if (pos.error) pos = cvLast(text, p.position, head, c);
    } else if (p?.position) pos = cvLast(text, p.position, head, d.start);
    if (pos.error) {
      problems.push(`${label}: не нашёл должность`);
      continue;
    }
    if (!free(pos) || !free(d)) {
      problems.push(`${label}: пересекается с другим разделом`);
      continue;
    }
    ranges.push({ key: `p:${id}`, ...pos }, { key: `d:${id}`, ...d });
    const period = String(p?.period ?? '').trim();
    places.push({
      id,
      hhId: null,
      company: company && c >= lo ? company : '',
      period: period && text.slice(head, d.start).includes(period) ? period : '',
      position: text.slice(pos.start, pos.end),
      description: text.slice(d.start, d.end),
    });
    lo = d.end;
  }
  ranges.sort((x, y) => x.start - y.start);
  let template = '';
  let last = 0;
  for (const r of ranges) {
    template += `${text.slice(last, r.start)}⟦${r.key}⟧`;
    last = r.end;
  }
  template += text.slice(last);
  const field = (key) => {
    const r = ranges.find((x) => x.key === key);
    return r ? text.slice(r.start, r.end) : '';
  };
  const cv = {
    v: 1,
    places,
    resumes: [{ id: 'r1', hh: null, template, title: field('title'), about: field('about'), keySkills: [] }],
  };
  return cvRender(cv) === text ? { cv, problems } : { error: 'lossy' };
}

// ---------- Сверка с hh (часть D, S3) ----------

// Одинаковы ли куски для сверки: без разницы в пробелах, кавычках, тире, регистре и точке в конце
function cvSame(a, b) {
  const n = (s) => normMap(String(s ?? '')).out.toLowerCase().replace(/[.\s]+$/, '');
  return n(a) === n(b);
}
// Чужой текст (с hh) без служебных знаков разметки
const cvClean = (s) => String(s ?? '').replace(/[⟦⟧]/g, '').trim();

// Поставить значение поля раздела. У должности и «О себе» без метки — новый раздел в конец текста резюме
function cvSet(cv, key, value, i = 0) {
  const v = cvClean(value);
  const r = cv.resumes[i];
  if (key === 'title' || key === 'about') {
    if (!r.template.includes(`⟦${key}⟧`)) r.template += `\n\n## ${key === 'title' ? 'Желаемая должность' : 'О себе'}\n⟦${key}⟧`;
    r[key] = v;
    return;
  }
  const place = cv.places.find((p) => p.id === key.slice(2));
  if (place) place[key[0] === 'p' ? 'position' : 'description'] = v;
}

// Даты hh (2025-08-01) → «авг 2025 — сен 2026»; без конца — «по настоящее время»
const CV_MONTHS = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
function cvMonth(d) {
  const m = String(d ?? '').match(/^(\d{4})-(\d{2})/);
  return m ? `${CV_MONTHS[Number(m[2]) - 1]} ${m[1]}` : '';
}
const cvPeriod = (start, end) => [cvMonth(start), cvMonth(end) || 'по настоящее время'].filter(Boolean).join(' — ');

// Место работы с hh — в бота: в конец блока опыта (после описания последнего места; мест нет — в конец текста).
// Заголовок — как у мест владельца: «### Компания — должность (период)»
function cvAddPlace(cv, h, i = 0) {
  const id = `e${Math.max(0, ...cv.places.map((p) => Number(p.id.slice(1)))) + 1}`;
  const company = cvClean(h.company);
  const period = cvPeriod(h.start, h.end);
  cv.places.push({ id, hhId: h.hhId ?? null, company, period, position: cvClean(h.position), description: cvClean(h.description) });
  const r = cv.resumes[i];
  const block = `\n\n### ${company} — ⟦p:${id}⟧${period ? ` (${period})` : ''}\n⟦d:${id}⟧`;
  const last = [...r.template.matchAll(/⟦d:e\d{1,3}⟧/g)].at(-1);
  const at = last ? last.index + last[0].length : r.template.length;
  r.template = r.template.slice(0, at) + block + r.template.slice(at);
  return id;
}

// Компания для сопоставления: без формы организации, кавычек и регистра
const cvCompanyKey = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/["«»“”„']/g, '')
    .replace(/(^|\s)(ооо|оао|зао|пао|ао|ип|llc|ltd|inc|gmbh)(?=\s|$)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// Места бота ↔ места hh: та же компания (или одно название внутри другого); несколько — тот же год начала.
// → { pairs: [{ place, hh }], onlyHh: места hh без пары }
function cvMatchPlaces(cv, hhPlaces) {
  const free = [...(hhPlaces ?? [])];
  const pairs = [];
  for (const place of cv.places) {
    const k = cvCompanyKey(place.company);
    const cands = free.filter((h) => {
      const hk = cvCompanyKey(h.company);
      return k && hk && (hk === k || (Math.min(k.length, hk.length) >= 3 && (hk.includes(k) || k.includes(hk))));
    });
    const year = (h) => String(h.start ?? '').slice(0, 4);
    const h = cands.find((x) => year(x) && place.period.includes(year(x))) ?? cands[0];
    if (!h) continue;
    free.splice(free.indexOf(h), 1);
    pairs.push({ place, hh: h });
  }
  return { pairs, onlyHh: free };
}

